/* @autogenerated */
import { inject } from '@angular/core';
import { CanActivateFn } from '@angular/router';
import { AppStateService } from '@shared/context/state/app-state.service';

/**
 * Aplica el idioma y el tenant de la URL (`/:language/:tenant/...`) antes que las guardas de las rutas hijas.
 * Si una de ellas redirige (p. ej. a `/unauthorized`), la página de destino ya sale en el idioma de la URL.
 */
export const urlContextGuard: CanActivateFn = (route) => {
  const state = inject(AppStateService);
  const language = route.paramMap.get('language');
  const tenant = route.paramMap.get('tenant');
  if (language) {
    state.language.set(language);
  }
  if (tenant) {
    state.tenant.set(tenant);
  }
  return true;
};
